#pragma once

namespace fmt {

template <class T>
struct type_identity {
    using type = T;
};

template <class... Args>
struct basic_format_string {
    consteval basic_format_string(const char* text) : text(text) {}

    const char* text;
};

template <class... Args>
using format_string = basic_format_string<typename type_identity<Args>::type...>;

template <class... Args>
void print(format_string<Args...> format, Args&&... args) {}

}  // namespace fmt

[[gnu::format(printf, 1, 2)]] int log_line(const char* format, ...);
[[gnu::format(scanf, 1, 2)]] int read_line(const char* format, ...);

struct Logger {
    [[gnu::format(printf, 2, 3)]] void log(const char* format, ...);
    [[gnu::format(printf, 2, 3)]] void operator()(const char* format, ...);
};

#include "fmt.h"

void report(Logger logger, int count, double ratio, const char* name) {
    fmt::print("{} items, {:>8.2f} ratio, {{braces}}\n", count, ratio);
    log_line("%s: %d of %-8.3f%%\n", name, count, ratio);
    log_line(R"(%d raw \n)", count);
    log_line("%2$s: %1$*3$d\n", count, name, 8);
    logger.log("%d member", count);
    logger("%d call", count);
    const char* plain = "{} stays text";
}

void scan(char** owned, char* word, int* count) {
    read_line("%ms %15[^,\n], %*d %d", owned, word, count);
}
